#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_standard_kind_resolves_through_the_sorted_descriptor_table() {
        assert!(
            EVENT_KIND_DESCRIPTORS
                .windows(2)
                .all(|pair| pair[0].kind < pair[1].kind)
        );
        for kind in EventKind::ALL {
            assert_eq!(
                kind.descriptor().map(|descriptor| descriptor.kind),
                Some(kind.as_str())
            );
        }
    }

    #[test]
    fn every_registered_cell_family_uses_its_generated_plane() {
        for descriptor in EVENT_KIND_DESCRIPTORS {
            let mut families = descriptor
                .cell_writes
                .iter()
                .filter_map(|write| write.cell_family.map(CellFamilyId::as_str))
                .collect::<Vec<_>>();
            if let Some(cell_family) = descriptor.cell_family {
                families.push(cell_family);
            }
            for cell_family in families {
                assert_eq!(
                    cba_cell_family_plane(cell_family).map(CbaEffectPlane::as_str),
                    descriptor.plane,
                    "cell family {cell_family} drifted from its event descriptor",
                );
            }
        }
    }

    #[test]
    fn every_cell_family_round_trips_through_its_generated_id() {
        for id in CellFamilyId::ALL {
            assert_eq!(CellFamilyId::from_wire(id.as_str()), Some(*id));
        }
    }
}
